select
id, node_name, description, server_names, dest, is_deleted, create_user, update_user, create_time, update_time,
status, available_status
from relay_node

    1 = 1 and is_deleted = 0

        and id = #{id}


        and node_name = #{nodeName}


        and description = #{description}


        and server_names = #{serverNames}


        and dest = #{dest}

select
id, node_name, description, server_names, dest, is_deleted, create_user, update_user, create_time, update_time,
status
from relay_node

    1 = 1 and is_deleted = 0

        and id = #{dto.id}


